// Merge configuration from all trigger types
const input = $input.first().json;

// Parse custom extractors
let customExtractors = [];
try {
  const extractorInput = input.customExtractors || input['Custom Extractors (JSON array)'] || '[]';
  customExtractors = JSON.parse(extractorInput);
} catch (e) {
  customExtractors = [];
}

// Parse source config
let sourceConfig = {};
try {
  sourceConfig = JSON.parse(input.sourceConfig || input['Source Config (JSON)'] || '{}');
} catch (e) {
  sourceConfig = {};
}

// Parse export config
let exportConfig = {};
try {
  exportConfig = JSON.parse(input.exportConfig || input['Export Config (JSON)'] || '{}');
} catch (e) {
  exportConfig = {};
}

const config = {
  // Metadata
  projectName: input.projectName || input['Project Name'] || 'Transcript Analysis',
  dashboardTitle: input.dashboardTitle || input['Dashboard Title'] || 'Transcript Analysis Dashboard',
  participants: (input.participants || input['Participants'] || '').split(',').map(p => p.trim()).filter(Boolean),
  tags: (input.tags || input['Tags'] || '').split(',').map(t => t.trim()).filter(Boolean),
  dateRange: input.dateRange || input['Date Range'] || '',

  // Styling
  primaryColor: input.primaryColor || input['Primary Brand Color'] || '#2563eb',
  secondaryColor: input.secondaryColor || input['Secondary Brand Color'] || '#7c3aed',
  accentColor: input.accentColor || '#f59e0b',
  logoUrl: input.logoUrl || input['Logo URL'] || '',
  customCss: input.customCss || input['Custom CSS'] || '',
  stylingInstructions: input.stylingInstructions || input['Styling Instructions'] || '',

  // Processing
  outputFormat: input.outputFormat || input['Output Format'] || 'Both HTML and JSON',
  processingMode: input.processingMode || input['Processing Mode'] || 'Full (reprocess all)',
  sectionsToInclude: input.sectionsToInclude || input['Sections to Include'] || 'all',

  // Custom extractors
  customExtractors,

  // Quality review
  enableQualityReview: (input.enableQualityReview || input['Enable Quality Review Loop'] || 'Yes').includes('Yes'),
  maxQualityIterations: parseInt(input.maxQualityIterations || input['Max Quality Iterations'] || '3'),

  // Source integration
  sourceIntegration: input.sourceIntegration || input['Source Integration'] || 'Local files (/transcripts/)',
  sourceConfig,

  // Export destinations
  exportDestinations: (input.exportDestinations || input['Export Destinations'] || 'local').split(',').map(d => d.trim().toLowerCase()),
  exportConfig,

  // Notifications
  notificationWebhook: input.notificationWebhook || input['Notification Webhook'] || '',

  // Internal
  runId: `run-${Date.now()}`,
  startedAt: new Date().toISOString()
};

// Derived flags
config.generateHtml = config.outputFormat.includes('HTML') || config.outputFormat.includes('Both');
config.generateJson = config.outputFormat.includes('JSON') || config.outputFormat.includes('Both');
config.incrementalMode = config.processingMode.includes('Incremental');
config.sections = config.sectionsToInclude === 'all' 
  ? ['questions', 'topics', 'tools', 'sessions', 'graph', 'summary', 'heatmap']
  : config.sectionsToInclude.split(',').map(s => s.trim().toLowerCase());

return [{ json: { config } }];

const config = $input.first().json.config;

const status = {
  runId: config.runId,
  status: 'initializing',
  phase: 'source_integration',
  startedAt: config.startedAt,
  config: {
    projectName: config.projectName,
    outputFormat: config.outputFormat,
    sourceIntegration: config.sourceIntegration,
    exportDestinations: config.exportDestinations
  },
  progress: { filesDiscovered: 0, filesProcessed: 0, filesSkipped: 0, filesFailed: 0 },
  errors: [],
  lastUpdated: new Date().toISOString()
};

return [{ json: { config, status } }];

const config = $('Merge Configuration').first().json.config;
const response = $json.result;

let files = [];
try {
  const match = response.match(/\[[\s\S]*\]/);
  if (match) files = JSON.parse(match[0]);
} catch (e) {
  throw new Error('Failed to parse file list: ' + e.message);
}

// Filter for incremental mode
const processableFiles = files.map(file => {
  const fileHash = `${file.filename}-${file.sizeBytes}-${file.modifiedTime}`;
  return {
    ...file,
    outputPath: `/transcripts/summaries/${file.filename.replace(/\.(vtt|srt|txt|json)$/i, '.md')}`,
    shouldProcess: !config.incrementalMode, // Simplified - real impl would check state file
    fileHash
  };
});

const toProcess = processableFiles.filter(f => f.shouldProcess);
const toSkip = processableFiles.filter(f => !f.shouldProcess);

return [{
  json: {
    config,
    allFiles: processableFiles,
    filesToProcess: toProcess,
    skippedFiles: toSkip,
    status: { phase: 'file_discovery_complete', progress: { filesDiscovered: files.length, filesToProcess: toProcess.length } }
  }
}];

const data = $input.first().json;
const files = data.filesToProcess;

if (files.length === 0) {
  return [{ json: { ...data, noFilesToProcess: true } }];
}

return files.map((file, index) => ({
  json: {
    ...file,
    config: data.config,
    customExtractors: data.config.customExtractors,
    totalFiles: files.length,
    fileIndex: index + 1
  }
}));

const items = $input.all();
const config = items[0]?.json?.config || $('Parse & Filter Files').first().json.config;

const results = items.map(item => item.json);
const successful = results.filter(r => r.success);
const failed = results.filter(r => !r.success);

return [{
  json: {
    config,
    results: { successful, failed, skipped: $('Parse & Filter Files').first().json.skippedFiles || [] },
    status: { phase: 'analysis_complete', progress: { filesProcessed: successful.length, filesFailed: failed.length } }
  }
}];

