function parseReview(result) {
  if (!result) return { overall_pass: false, issues: ['No result'], recommendations: [] };
  try {
    return JSON.parse(result);
  } catch (e) {
    const match = result.match?.(/\{[\s\S]*\}/);
    if (match) try { return JSON.parse(match[0]); } catch {}
    return { overall_pass: false, issues: ['Parse error'], recommendations: [] };
  }
}

const items = $input.all();
const iteration = $('Init Quality Loop').first()?.json?.iteration || 1;

const content = parseReview(items.find(i => i.json.result?.includes('content'))?.json?.result);
const visual = parseReview(items.find(i => i.json.result?.includes('visual'))?.json?.result);
const technical = parseReview(items.find(i => i.json.result?.includes('technical'))?.json?.result);

const allPass = content.overall_pass && visual.overall_pass && technical.overall_pass;
const allIssues = [...(content.issues||[]), ...(visual.issues||[]), ...(technical.issues||[])];
const allRecs = [...(content.recommendations||[]), ...(visual.recommendations||[]), ...(technical.recommendations||[])];

return [{ json: { allPass, iteration, maxIterations: 3, reviews: { content, visual, technical }, allIssues, allRecommendations: allRecs, totalIssues: allIssues.length } }];

